# Search for repeated sub-rectangles: does the 8-region appear elsewhere with 8->? mapping
from collections import defaultdict
H,W=a.shape
pats=defaultdict(list)
for h in range(2,8):
  for w in range(2,10):
    for i in range(H-h+1):
      for j in range(W-w+1):
        sub=tuple(tuple(int(x) for x in row) for row in a[i:i+h,j:j+w])
        if 8 in sub:
          # pattern with 8 as wildcard
          key=(h,w,tuple(8 if x==8 else x for row in sub for x in row))
          pats[key].append((i,j,sub))
for k,v in pats.items():
  if len(v)>1:
    print(k[:2], [(i,j) for i,j,s in v])

eights=np.argwhere(a==8)
best=[]
for di in range(-15,16):
  for dj in range(-13,14):
    pts=eights+np.array([di,dj])
    if ((pts[:,0]>=0)&(pts[:,0]<16)&(pts[:,1]>=0)&(pts[:,1]<14)).all():
      vals=a[pts[:,0],pts[:,1]]
      hits=(vals==0).sum()
      if hits>=5: best.append((hits,di,dj,vals.tolist()))
best.sort(reverse=True)
print(best[:10])

a=np.array(g)
pts=np.argwhere(a==8); p0=pts.min(0)
pat=[tuple(p) for p in (pts-p0)]
H,W=a.shape
out=a.copy()
for di in range(H):
  for dj in range(W):
    cells=[(di+dy,dj+dx) for dy,dx in pat]
    if all(0<=y<H and 0<=x<W and a[y,x] in (0,8) for y,x in cells):
        for y,x in cells: out[y,x]=8
print('new 8s:', np.argwhere((out==8)&(a!=8)).tolist())
print('total 8s', (out==8).sum())
for r in out: print(' '.join(map(str,r)))
